import json
import os
import pickle
from contextlib import asynccontextmanager
from typing import List

import numpy as np
from fastapi import FastAPI
from pydantic import BaseModel, field_validator

MODEL_PATH = '/app/models/best_model.pkl'
COMPARISON_PATH = '/app/output/model_comparison.json'
N_FEATURES = 8
state = {'model': None, 'model_name': None, 'model_type': None}


@asynccontextmanager
async def lifespan(app):
    with open(MODEL_PATH, 'rb') as f:
        model = pickle.load(f)
    name = 'best_model'
    if os.path.exists(COMPARISON_PATH):
        with open(COMPARISON_PATH) as f:
            name = json.load(f).get('best_model_name', name)
    state['model'] = model
    state['model_name'] = name
    state['model_type'] = type(model).__name__
    yield


app = FastAPI(title='California Housing Price API', lifespan=lifespan)


class PredictRequest(BaseModel):
    features: List[float]

    @field_validator('features')
    @classmethod
    def check_len(cls, v):
        if len(v) != N_FEATURES:
            raise ValueError('features must contain exactly 8 values')
        return v


class BatchRequest(BaseModel):
    features_list: List[List[float]]

    @field_validator('features_list')
    @classmethod
    def check_len(cls, v):
        for row in v:
            if len(row) != N_FEATURES:
                raise ValueError('each inner list must contain exactly 8 values')
        return v


@app.get('/health')
def health():
    return {'status': 'healthy', 'model_loaded': state['model'] is not None}


@app.get('/model-info')
def model_info():
    return {
        'model_name': state['model_name'],
        'model_type': state['model_type'],
        'features_count': N_FEATURES,
    }


@app.post('/predict')
def predict(req: PredictRequest):
    X = np.array([req.features], dtype=float)
    pred = float(state['model'].predict(X)[0])
    return {'prediction': pred, 'model_name': state['model_name']}


@app.post('/predict-batch')
def predict_batch(req: BatchRequest):
    if len(req.features_list) == 0:
        preds = []
    else:
        X = np.array(req.features_list, dtype=float)
        preds = [float(p) for p in state['model'].predict(X)]
    return {
        'predictions': preds,
        'model_name': state['model_name'],
        'count': len(preds),
    }
